        let bes0: [String: String] = ["tab.overview": "Resumen", "tab.team": "Equipo", "tab.stats": "Estadísticas", "tab.insights": "Indicadores", "nav.settings": "Ajustes", "mySpots.title": "Mis spots", "mySpots.empty": "Aún no hay sesiones en ningún spot.", "mySpots.last": "última {d}", "mySpots.since": "desde {d}", "mySpots.sports": "Deportes", "mySpots.all": "Todos ({n})", "sessions.title": "Sesiones", "tab.weather": "Tiempo", "tab.descriptions": "Descripciones", "tab.spotPage": "Página del spot", "phome.profileHint": "Tu página de perfil, tal como la pueden ver los demás.", "phome.asFriends": "Amigos", "phome.asAll": "Todos", "phome.previewHidden": "Tu página de perfil está oculta para los demás; solo tus amigos la ven.", "ptab.privacy": "Privacidad", "ptab.watches": "Relojes", "ptab.me": "Yo", "ptab.riding": "Navegación", "ptab.display": "Pantalla", "ptab.account": "Cuenta", "gear.title": "Equipo", "gear.mastShim": "Mástil y shim", "gear.searchHint": "Busca por marca o modelo para añadir algo.", "gear.noHits": "Sin resultados.", "tab.rankings": "Récords y clasificación", "tab.media": "Medios", "land.teamsTitle": "Equipos y eventos", "tab.map": "Mapa", "tab.list": "Lista", "tab.routes": "Rutas", "tab.watchAccounts": "Reloj y cuentas", "period.yesterday": "Ayer", "tab.noRecords": "Todavía no hay récords aquí.", "setup.stabSearch": "Buscar estabilizador…", "foils.hint": "Marca tus foils y elige uno por defecto (★). Modificable por sesión.", "profile.avatar": "Foto de perfil", "profile.dataTitle": "Datos y cuenta", "profile.calculator": "Calculadora de foil", "brett.erkl.titel": "¿Qué es la actitud de la tabla?", "brett.erkl.was": "Si tu móvil va fijado a la tabla durante la sesión, su giroscopio mide cómo cabecea y alabea la tabla, directamente en la fuente en lugar de en la muñeca."]
        mes.merge(bes0) { a, _ in a }
        let bes1: [String: String] = ["brett.erkl.wie": "Cómo funciona: mete el móvil en una funda estanca, fíjalo plano sobre la cubierta e inicia la grabación en la app Pumpfoil del móvil. El reloj puede grabar a la vez. Normalmente el análisis detecta solo que el móvil iba en la tabla.", "brett.erkl.bringt": "Qué te aporta: ves lo estable que va tu tabla al bombear, cuánto cabecea y alabea en cada pump y si cambia entre foils, curvas y rectas. Cada grabación así también ayuda a mejorar la detección de pumps para el reloj.", "brett.erkl.daten": "Los datos que obtienes: cabeceo y alabeo por pump, inclinación, cadencia, curvas frente a rectas y el movimiento vertical (cuando el ritmo de pump se detecta con seguridad), por tramo y aquí como resumen de todos los tramos y por foil.", "brett.erkl.mehr": "Más información", "region.earth": "Tierra", "region.eu": "Europa", "region.af": "África", "region.as": "Asia", "region.na": "América del Norte", "region.sa": "América del Sur", "region.oc": "Oceanía", "profile.landNone": "Sin indicar", "share.errImage": "No se pudo crear la imagen", "spot.windTitle": "Ventana de viento", "spot.windText": "{n} sesiones con viento, sobre todo a {a}–{b} km/h", "spot.windNote": "De dónde venía el viento en las sesiones de wing, kite y parawing en este spot (viento del modelo).", "tab.noData": "Todavía no hay datos aquí.", "fontscale.label": "Tamaño del texto", "fontscale.hint": "Agranda todo para una mejor legibilidad.", "sd.avgHrTotal": "Ø pulso total", "sd.whoLiked": "¿Quién?", "sd.likes": "Me gusta", "comments.title": "Comentarios", "comments.empty": "Aún no hay comentarios. ¡Escribe el primero!", "comments.placeholder": "Escribe un comentario …", "comments.offOwner": "Los comentarios están desactivados para tus sesiones.", "comments.offLink": "Activarlos en tu perfil", "comments.settingHint": "Otros pueden comentar tus sesiones. Puedes borrar los comentarios de otros en tus sesiones. Si los desactivas, los comentarios se ocultan para todos, también los ya escritos.", "comments.settingSwitch": "Permitir comentarios en mis sesiones", "act.title": "Nuevos comentarios y me gusta", "act.comment": "ha comentado", "act.like": "le gusta tu sesión", "act.likeMany": "y {n} más han dado me gusta a tu sesión", "act.session": "Sesión del {d}", "profile.land": "Nacionalidad", "profile.landHint": "Opcional. Si la indicas, tu bandera aparece en las clasificaciones y en sus imágenes para compartir.", "tab.events": "Eventos", "tab.logbook": "Bitácora", "tab.rules": "Reglas", "team.einladungUngueltig": "Este enlace de invitación ya no es válido. Pide uno nuevo al líder del equipo.", "team.feed30": "Sesiones de los miembros del equipo de los últimos 30 días.", "team.alleMeine": "Todos mis equipos", "sessions.uploadReplaceAsk": "Esta sesión ya existe (sesión #{id}), pero el archivo es distinto. ¿Borrar la sesión antigua y sustituirla por este archivo?\n\nPara solo recortarla no hace falta un archivo nuevo: usa «{trim}» en la sesión.", "team.regeln.intro": "Así funcionan los equipos en pumpfoil.org: quién ve qué, cómo se puntúa y qué pasa al eliminar algo.", "team.regeln.was.titel": "¿Qué es un equipo?"]
        mes.merge(bes1) { a, _ in a }
        let bes2: [String: String] = ["team.regeln.was.text": "Un grupo fijo con sus propias clasificaciones, eventos y un chat del equipo.\nCualquiera puede crear equipos, también varios, y estar en varios equipos.\nUn equipo nuevo funciona al instante, con enlaces de invitación.", "team.regeln.rollen.titel": "Roles", "team.regeln.rollen.text": "El líder puede hacerlo todo: ajustes, clasificaciones, eventos, nombrar moderadores, ceder el liderazgo y eliminar el equipo.\nLos moderadores aceptan o rechazan solicitudes, quitan miembros y crean eventos. No cambian nada más.\nLos miembros ven todo en el equipo y pueden salir en cualquier momento.\nEl líder solo puede salir después de ceder el liderazgo.", "team.regeln.beitreten.titel": "Unirse", "team.regeln.beitreten.text": "Si un equipo admite solicitudes de ingreso, su página muestra un botón «Unirse». Según el ajuste, eres miembro al instante, o decide el líder o un moderador.\nHay dos enlaces de invitación: uno con el que eres miembro al instante y otro con el que envías una solicitud. Ambos existen también como código QR.\nQuien aún no tiene cuenta crea una y después ya está en el equipo o ha enviado la solicitud.\nUn enlace nuevo sustituye al anterior, que deja de funcionar.\nCada vez que te unes, aceptas que las clasificaciones del equipo puedan ser públicas, aunque ahora no lo sean.\nCon una solicitud, el líder y los moderadores ven en qué spots y deportes has estado hasta ahora (solo el número de sesiones).", "team.regeln.oeffentlich.titel": "Qué es público", "team.regeln.oeffentlich.text": "Dentro, un equipo puede hacer de todo. Hacia fuera solo aparece cuando hemos revisado y aprobado su nombre, dirección, descripción, escudo y color.\nLa imagen del equipo pasa por la misma aprobación que el escudo. Qué parte se ve lo elige el líder sin nueva aprobación; si la quita, desaparece al instante también de la página pública.\nSi un equipo aprobado cambia su apariencia, se aplica al instante dentro del equipo y, en público, tras una nueva aprobación.\nLos equipos aprobados aparecen en la página «Todos los equipos», y sus eventos en curso y próximos en la comunidad.\nSi el líder hace públicas las clasificaciones, cualquiera las ve, incluso sin iniciar sesión, pero solo el puesto, el nombre visible, las iniciales y el valor. Las sesiones, los spots, las fechas y las fotos de perfil solo los ven los usuarios con sesión iniciada.\nLos buscadores no indexan las páginas de equipos.\nEl líder decide quién ve la lista de miembros: solo los miembros o todos los usuarios con sesión iniciada.", "team.regeln.bestenlisten.titel": "Clasificaciones", "team.regeln.bestenlisten.text": "Cada persona cuenta una sola vez: su mejor valor en una sesión o, en los totales, todo lo del periodo elegido sumado.\nCuentan todas las sesiones de los miembros, también las de antes de unirse. Quien sale desaparece al instante de las listas.\nEn los eventos esto solo vale hasta el final, ver «Eventos».\nSe aplican los mismos filtros que en los récords de la comunidad: no cuentan las grabaciones eliminadas, denunciadas, sin asignar ni en curso.\nCada clasificación puede limitarse a un deporte, un rango de foils, grabaciones con datos de movimiento, el teléfono en la tabla o los spots del equipo.\nSi «Ocultar el lugar» está activado, la sesión nunca cuenta para un spot concreto.\nEn caso de empate, va delante quien consiguió el valor primero.", "team.regeln.statistik.titel": "Totales del equipo", "team.regeln.statistik.text": "Encima de las clasificaciones están los totales de todos los miembros en el periodo elegido: pumps, distancia y tiempo on-foil, sesiones, runs y cuántos miembros estuvieron activos.\nA propósito no hay una clasificación de equipo contra equipo.", "team.regeln.logbuch.titel": "Bitácora", "team.regeln.logbuch.text": "La bitácora registra quién batió qué récord del equipo y cuándo. Se actualiza cada noche.\nLa primera entrada de una clasificación es el estado de la primera noche después de crearla.\nEn los mejores valores cuenta cada mejora, también la propia. En los totales solo cuenta cuando alguien pasa a liderar.\nSi un récord baja porque se eliminó una sesión o alguien salió, se ajusta en silencio, sin entrada.", "team.regeln.chat.titel": "Chat del equipo", "team.regeln.chat.text": "Solo los miembros activos pueden leer y escribir en el chat del equipo. Quien solo ha enviado una solicitud no lo ve.\nNo aparece en ningún sitio para los demás, ni siquiera entre los chats activos.\nQuien sale o es quitado pierde el acceso al instante y ya no recibe notificaciones.", "team.regeln.loeschen.titel": "Eliminar un equipo", "team.regeln.loeschen.text": "Solo el líder puede eliminar un equipo, y solo escribiendo el nombre del equipo para confirmar.\nEntonces el equipo desaparece para todos: membresías, clasificaciones, bitácora, eventos y chat del equipo. De momento guardamos los datos para poder restaurar un equipo borrado por error.\nLa dirección del equipo queda bloqueada y nunca se asigna a otro equipo.", "team.regeln.konto.titel": "Cuando se elimina una cuenta", "team.regeln.konto.text": "La persona desaparece de todos los equipos y clasificaciones, y también de los resultados de eventos congelados. Los puestos de debajo suben.\nSi lideraba un equipo, toma el relevo el moderador más antiguo y, si no hay, el miembro más antiguo. Si no queda nadie, el equipo se elimina.", "team.regeln.haftung.titel": "Responsabilidad", "team.regeln.haftung.text": "Los eventos los organizan los propios equipos. pumpfoil.org no tiene ninguna influencia sobre los eventos ni sobre las promesas que se hagan en ellos, económicas o de otro tipo, y no asume ninguna responsabilidad. Queda excluida la vía judicial. Los pagos y cualquier otro acuerdo los resuelven organizadores y participantes, independientemente de pumpfoil.org.\nDel mismo modo, pumpfoil.org no asume ninguna responsabilidad sobre si los valores y datos medidos son correctos o han sido manipulados. Se muestra lo que el código fuente público en GitHub calcula a partir de los datos subidos; no hay más promesas.", "team.regeln.events.titel": "Eventos", "notif.typeComment": "Comentarios en mis sesiones"]
        mes.merge(bes2) { a, _ in a }
        r["es"] = mes
