        mfi.merge(bfi0) { a, _ in a }
        let bfi1: [String: String] = ["brett.erkl.wie": "Näin se toimii: laita puhelin vesitiiviiseen koteloon, kiinnitä se tasaisesti kanteen ja aloita tallennus puhelimen Pumpfoil-sovelluksessa. Kello voi tallentaa samaan aikaan. Analyysi huomaa yleensä itse, että puhelin oli laudalla.", "brett.erkl.bringt": "Mitä siitä saat: näet, kuinka vakaasti lauta kulkee pumpatessa, kuinka paljon se nyökkää ja kallistuu jokaisella pumpulla ja eroaako se foilien, kaarteiden ja suorien välillä. Jokainen tällainen tallennus auttaa myös parantamaan kellon pumppujen tunnistusta.", "brett.erkl.daten": "Saamasi tiedot: nyökkäys ja kallistus pumppua kohden, kallistuma, tahti, kaarteet vastaan suorat ja pystyliike (kun pumpputahti tunnistetaan varmasti) – lenkeittäin ja tässä yhteenvetona kaikista lenkeistä ja foileittain.", "brett.erkl.mehr": "Lue lisää", "region.earth": "Maa", "region.eu": "Eurooppa", "region.af": "Afrikka", "region.as": "Aasia", "region.na": "Pohjois-Amerikka", "region.sa": "Etelä-Amerikka", "region.oc": "Oseania", "profile.landNone": "Ei ilmoitettu", "share.errImage": "Kuvaa ei voitu luoda", "spot.windTitle": "Tuuli-ikkuna", "spot.windText": "{n} tuulisessiota, yleensä {a}–{b} km/h", "spot.windNote": "Mistä tuuli tuli wing-, kite- ja parawing-sessioissa tällä spotilla (mallituuli).", "tab.noData": "Täällä ei ole vielä tietoja.", "fontscale.label": "Tekstin koko", "fontscale.hint": "Suurenna kaikki paremman luettavuuden vuoksi.", "sd.avgHrTotal": "Ø syke yhteensä", "sd.whoLiked": "Kuka?", "sd.likes": "Tykkäykset", "comments.title": "Kommentit", "comments.empty": "Ei vielä kommentteja. Kirjoita ensimmäinen!", "comments.placeholder": "Kirjoita kommentti …", "comments.offOwner": "Kommentit on poistettu käytöstä sessioillasi.", "comments.offLink": "Ota käyttöön profiilissa", "comments.settingHint": "Muut voivat kommentoida sessioitasi. Voit poistaa muiden kommentteja sessioidesi alta. Kun ne ovat pois päältä, kommentit on piilotettu kaikilta, myös jo kirjoitetut.", "comments.settingSwitch": "Salli kommentit sessioihini", "act.title": "Uudet kommentit & tykkäykset", "act.comment": "kommentoi", "act.like": "tykkää sessiostasi", "act.likeMany": "ja {n} muuta tykkäävät sessiostasi", "act.session": "Sessio {d}", "profile.land": "Kansallisuus", "profile.landHint": "Vapaaehtoinen. Jos asetat sen, lippusi näkyy tulostauluissa ja niiden jaettavissa kuvissa.", "tab.events": "Tapahtumat", "tab.logbook": "Lokikirja", "tab.rules": "Säännöt", "team.einladungUngueltig": "Tämä kutsulinkki ei ole enää voimassa. Pyydä tiimin vetäjältä uusi.", "team.feed30": "Tiimin jäsenten sessiot viimeiseltä 30 päivältä.", "team.alleMeine": "Kaikki tiimini", "sessions.uploadReplaceAsk": "Tämä ajo on jo täällä (sessio #{id}), mutta tiedosto on eri. Poistetaanko vanha sessio ja korvataan se tällä tiedostolla?\n\nPelkkään lyhentämiseen ei tarvita uutta tiedostoa: käytä sessiossa kohtaa ”{trim}”.", "team.regeln.intro": "Näin tiimit toimivat pumpfoil.orgissa: kuka näkee mitä, miten tulokset lasketaan ja mitä poistaessa tapahtuu.", "team.regeln.was.titel": "Mikä on tiimi?"]
