        let bcs0: [String: String] = ["tab.overview": "Přehled", "tab.team": "Tým", "tab.stats": "Statistiky", "tab.insights": "Ukazatele", "nav.settings": "Nastavení", "mySpots.title": "Moje spoty", "mySpots.empty": "Zatím žádné session na spotu.", "mySpots.last": "naposledy {d}", "mySpots.since": "od {d}", "mySpots.sports": "Sporty", "mySpots.all": "Vše ({n})", "sessions.title": "Vyjížďky", "tab.weather": "Počasí", "tab.descriptions": "Popisy", "tab.spotPage": "Stránka spotu", "phome.profileHint": "Tvoje profilová stránka, jak ji mohou vidět ostatní.", "phome.asFriends": "Přátelé", "phome.asAll": "Všichni", "phome.previewHidden": "Tvoje profilová stránka je pro ostatní skrytá, vidí ji jen přátelé.", "ptab.privacy": "Soukromí", "ptab.watches": "Hodinky", "ptab.me": "Já", "ptab.riding": "Jízda", "ptab.display": "Zobrazení", "ptab.account": "Účet", "gear.title": "Vybavení", "gear.mastShim": "Stěžeň a shim", "gear.searchHint": "Hledej podle značky nebo modelu a přidej.", "gear.noHits": "Žádné výsledky.", "tab.rankings": "Rekordy a žebříček", "tab.media": "Média", "land.teamsTitle": "Týmy a akce", "tab.map": "Mapa", "tab.list": "Seznam", "tab.routes": "Trasy", "tab.watchAccounts": "Hodinky a účty", "period.yesterday": "Včera", "tab.noRecords": "Zatím tu nejsou žádné rekordy.", "setup.stabSearch": "Hledat stabilizátor…", "foils.hint": "Ulož si své foily a vyber jeden jako výchozí (★). Výchozí lze přepsat u každé vyjížďky.", "profile.avatar": "Profilový obrázek", "profile.dataTitle": "Data a účet", "profile.calculator": "Foil kalkulačka", "brett.erkl.titel": "Co je poloha prkna?", "brett.erkl.was": "Když máš telefon během vyjížďky pevně na prkně, jeho gyroskop měří, jak prkno kývá a naklání se – přímo u zdroje, ne na zápěstí."]
