        let bcs1: [String: String] = ["brett.erkl.wie": "Jak na to: dej telefon do vodotěsného obalu, připevni ho naplocho na palubu a spusť záznam v aplikaci Pumpfoil v telefonu. Hodinky můžou nahrávat současně. Že byl telefon na prkně, pozná vyhodnocení většinou samo.", "brett.erkl.bringt": "Co ti to dá: uvidíš, jak klidně prkno při pumpování leží, jak moc při každém pumpu kývá a naklání se a jestli se to liší mezi foily, zatáčkami a rovinkami. Každý takový záznam navíc pomáhá zlepšit rozpoznávání pumpů pro hodinky.", "brett.erkl.daten": "Jaká data dostaneš: kývání a náklon na pump, náklon, kadenci, zatáčky proti rovinkám a vertikální pohyb (jakmile je rytmus pumpování spolehlivě rozpoznán) – pro každou jízdu a tady jako přehled všech jízd a podle foilu.", "brett.erkl.mehr": "Více informací", "region.earth": "Země", "region.eu": "Evropa", "region.af": "Afrika", "region.as": "Asie", "region.na": "Severní Amerika", "region.sa": "Jižní Amerika", "region.oc": "Oceánie", "profile.landNone": "Neuvedeno", "share.errImage": "Obrázek se nepodařilo vytvořit", "spot.windTitle": "Větrné okno", "spot.windText": "{n} větrných session, většinou při {a}–{b} km/h", "spot.windNote": "Odkud foukal vítr při wing, kite a parawing session na tomto spotu (modelový vítr).", "tab.noData": "Zatím tu nejsou žádná data.", "fontscale.label": "Velikost písma", "fontscale.hint": "Pro lepší čitelnost zvětšit vše.", "sd.avgHrTotal": "Ø tep celkem", "sd.whoLiked": "Kdo?", "sd.likes": "Líbí se", "comments.title": "Komentáře", "comments.empty": "Zatím žádné komentáře. Napiš první!", "comments.placeholder": "Napsat komentář …", "comments.offOwner": "Komentáře jsou u tvých sessions vypnuté.", "comments.offLink": "Zapnout v profilu", "comments.settingHint": "Ostatní mohou komentovat tvé sessions. Cizí komentáře pod svými sessions můžeš smazat. Když je vypneš, komentáře jsou skryté pro všechny, i ty už napsané.", "comments.settingSwitch": "Povolit komentáře pod mými sessions", "act.title": "Nové komentáře & lajky", "act.comment": "okomentoval(a)", "act.like": "se líbí tvoje session", "act.likeMany": "a {n} další lajkují tvoji session", "act.session": "Session z {d}", "profile.land": "Národnost", "profile.landHint": "Nepovinné. Když ji vyplníš, tvoje vlajka se zobrazí v žebříčcích a jejich obrázcích ke sdílení.", "tab.events": "Akce", "tab.logbook": "Deník", "tab.rules": "Pravidla", "team.einladungUngueltig": "Tento odkaz s pozvánkou už neplatí. Požádej vedení týmu o nový.", "team.feed30": "Vyjížďky členů týmu za posledních 30 dní.", "team.alleMeine": "Všechny moje týmy", "sessions.uploadReplaceAsk": "Tahle jízda už tu je (session #{id}), ale soubor je jiný. Smazat starou session a nahradit ji tímto souborem?\n\nJen zkrátit jde i bez nového souboru: v session přes „{trim}“.", "team.regeln.intro": "Jak fungují týmy na pumpfoil.org: kdo co vidí, jak se hodnotí a co se stane při smazání.", "team.regeln.was.titel": "Co je tým?"]
        mcs.merge(bcs1) { a, _ in a }
        let bcs2: [String: String] = ["team.regeln.was.text": "Pevná skupina s vlastními žebříčky, akcemi a týmovým chatem.\nKaždý může zakládat týmy, i víc najednou, a být ve více týmech.\nNový tým funguje hned, přes odkazy s pozvánkou.", "team.regeln.rollen.titel": "Role", "team.regeln.rollen.text": "Vedoucí smí všechno: nastavení, žebříčky, akce, jmenování moderátorů, předání vedení a smazání týmu.\nModerátoři přijímají nebo odmítají žádosti, odebírají členy a zakládají akce. Nic jiného nemění.\nČlenové vidí v týmu všechno a můžou kdykoli odejít.\nVedoucí může odejít, až když předá vedení.", "team.regeln.beitreten.titel": "Přidání do týmu", "team.regeln.beitreten.text": "Pokud tým přijímá přihlášky, je na jeho stránce tlačítko „Přidat se“. Podle nastavení jsi hned členem, nebo rozhodne vedoucí či moderátor.\nJsou dva odkazy s pozvánkou: jeden, se kterým jsi hned členem, a druhý, kterým pošleš žádost. Oba jsou i jako QR kód.\nKdo ještě nemá účet, založí si ho a pak je rovnou v týmu, případně má žádost odeslanou.\nNově vytvořený odkaz nahradí starý, který pak přestane platit.\nKaždým vstupem souhlasíš s tím, že žebříčky týmu můžou být veřejné, i když zrovna nejsou.\nU žádosti vidí vedoucí a moderátoři, na kterých spotech a v jakých sportech jsi dosud jezdil (jen počet sessions).", "team.regeln.oeffentlich.titel": "Co je veřejné", "team.regeln.oeffentlich.text": "Uvnitř smí tým všechno. Navenek se objeví, až když jsme si jednou prohlédli a schválili jeho název, adresu, popis, znak a barvu.\nBanner týmu prochází stejným schválením jako znak. Kterou část je vidět, volí vedoucí bez nového schválení; když banner odebere, zmizí hned i z veřejné stránky.\nKdyž schválený tým změní svůj vzhled, v týmu to platí hned, navenek až po novém schválení.\nSchválené týmy jsou na stránce „Všechny týmy“, jejich probíhající a nadcházející akce v komunitě.\nKdyž vedoucí zveřejní žebříčky, vidí je každý, i bez přihlášení, ale jen pořadí, zobrazované jméno, iniciály a hodnotu. Vyjížďky, spoty, data a profilové fotky vidí jen přihlášení uživatelé.\nVyhledávače stránky týmů neindexují.\nKdo vidí seznam členů, určuje vedoucí: jen členové, nebo všichni přihlášení.", "team.regeln.bestenlisten.titel": "Žebříčky", "team.regeln.bestenlisten.text": "Za každého se počítá jen jeden záznam: nejlepší hodnota z jedné vyjížďky, nebo u součtů všechno ve zvoleném období dohromady.\nPočítají se všechny vyjížďky členů, i ty z doby před vstupem. Kdo odejde, hned ze žebříčků zmizí.\nU akcí to platí jen do konce, viz „Akce“.\nPlatí stejné filtry jako u komunitních rekordů: smazané, nahlášené, nezařazené a probíhající nahrávky se nepočítají.\nKaždý žebříček lze omezit na jeden sport, jeden rozsah foilů, nahrávky s pohybovými daty, telefon na desce nebo týmové spoty.\nKdyž je zapnuté „Skrýt místo“, vyjížďka se nikdy nezapočítá pro konkrétní spot.\nPři shodě je výš ten, kdo hodnotu zajel dřív.", "team.regeln.statistik.titel": "Týmové součty", "team.regeln.statistik.text": "Nad žebříčky jsou součty všech členů ve zvoleném období: pumpnutí, vzdálenost a čas na foilu, vyjížďky, jízdy a kolik členů bylo aktivních.\nŽebříček tým proti týmu záměrně není.", "team.regeln.logbuch.titel": "Deník", "team.regeln.logbuch.text": "Deník zaznamenává, kdo kdy překonal který týmový rekord. Aktualizuje se každou noc.\nPrvní záznam žebříčku je stav v první noci po jeho založení.\nU nejlepších hodnot se počítá každé zlepšení, i vlastní. U součtů se počítá jen to, když se někdo dostane do čela.\nKdyž rekord klesne, protože byla smazána vyjížďka nebo někdo odešel, upraví se to potichu, bez záznamu.", "team.regeln.chat.titel": "Týmový chat", "team.regeln.chat.text": "Týmový chat čtou a píšou do něj jen aktivní členové. Kdo jen poslal žádost, nevidí ho.\nPro ostatní se nikde neobjeví, ani mezi aktivními chaty.\nKdo odejde nebo je odebrán, hned ztratí přístup a nedostává už žádná upozornění.", "team.regeln.loeschen.titel": "Smazání týmu", "team.regeln.loeschen.text": "Smazat tým může jen vedoucí, a jen když pro potvrzení napíše název týmu.\nTým pak zmizí pro všechny: členství, žebříčky, deník, akce i týmový chat. Data zatím uchováváme, aby šel omylem smazaný tým obnovit.\nAdresa týmu zůstane zablokovaná a nikdy se nepřidělí jinému týmu.", "team.regeln.konto.titel": "Když se smaže účet", "team.regeln.konto.text": "Člověk zmizí ze všech týmů a žebříčků a také ze zmrazených výsledků akcí. Ti pod ním se posunou nahoru.\nPokud vedl tým, převezme ho nejdéle sloužící moderátor, jinak nejdéle sloužící člen. Pokud už nikdo nezbyl, tým se smaže.", "team.regeln.haftung.titel": "Odpovědnost", "team.regeln.haftung.text": "Akce pořádají samy týmy. pumpfoil.org nemá žádný vliv na akce ani na sliby v nich dané, finanční či jiné, a nepřebírá za ně žádnou odpovědnost. Právní cesta je vyloučena. Platby a všechny další dohody si pořadatelé a účastníci řeší sami, nezávisle na pumpfoil.org.\nStejně tak pumpfoil.org nepřebírá žádnou odpovědnost za to, zda jsou naměřené hodnoty a data správné nebo zda nebyly zmanipulovány. Zobrazuje se to, co z nahraných dat spočítá veřejný zdrojový kód na GitHubu; žádné další záruky neexistují.", "team.regeln.events.titel": "Akce", "notif.typeComment": "Komentáře k mým sessions"]
        mcs.merge(bcs2) { a, _ in a }
        r["cs"] = mcs
        var mpl: [String: String] = [:]
        let bpl0: [String: String] = ["tab.overview": "Przegląd", "tab.team": "Drużyna", "tab.stats": "Statystyki", "tab.insights": "Wskaźniki", "nav.settings": "Ustawienia", "mySpots.title": "Moje spoty", "mySpots.empty": "Brak jeszcze sesji na żadnym spocie.", "mySpots.last": "ostatnio {d}", "mySpots.since": "od {d}", "mySpots.sports": "Dyscypliny", "mySpots.all": "Wszystkie ({n})", "sessions.title": "Sesje", "tab.weather": "Pogoda", "tab.descriptions": "Opisy", "tab.spotPage": "Strona spotu", "phome.profileHint": "Twoja strona profilu, tak jak mogą ją zobaczyć inni.", "phome.asFriends": "Znajomi", "phome.asAll": "Wszyscy", "phome.previewHidden": "Twoja strona profilu jest ukryta dla innych; widzą ją tylko znajomi.", "ptab.privacy": "Prywatność", "ptab.watches": "Zegarki", "ptab.me": "Ja", "ptab.riding": "Pływanie", "ptab.display": "Wygląd", "ptab.account": "Konto", "gear.title": "Sprzęt", "gear.mastShim": "Maszt i shim", "gear.searchHint": "Szukaj po marce lub modelu, aby coś dodać.", "gear.noHits": "Brak wyników.", "tab.rankings": "Rekordy i ranking", "tab.media": "Media", "land.teamsTitle": "Drużyny i wydarzenia", "tab.map": "Mapa", "tab.list": "Lista", "tab.routes": "Trasy", "tab.watchAccounts": "Zegarek i konta", "period.yesterday": "Wczoraj", "tab.noRecords": "Nie ma tu jeszcze rekordów.", "setup.stabSearch": "Szukaj stabilizatora…", "foils.hint": "Zaznacz swoje foile i wybierz jeden jako domyślny (★). Domyślny można nadpisać w każdej sesji.", "profile.avatar": "Zdjęcie profilowe", "profile.dataTitle": "Dane i konto", "profile.calculator": "Kalkulator foili", "brett.erkl.titel": "Czym jest ustawienie deski?", "brett.erkl.was": "Jeśli telefon jest przymocowany do deski podczas sesji, jego żyroskop mierzy, jak deska kiwa się i przechyla – bezpośrednio u źródła, a nie na nadgarstku."]
        mpl.merge(bpl0) { a, _ in a }
        let bpl1: [String: String] = ["brett.erkl.wie": "Jak to zrobić: włóż telefon do wodoszczelnego etui, przymocuj go płasko na pokładzie i uruchom nagrywanie w aplikacji Pumpfoil na telefonie. Zegarek może nagrywać jednocześnie. Analiza zwykle sama rozpozna, że telefon był na desce.", "brett.erkl.bringt": "Co ci to daje: widzisz, jak stabilnie deska leży podczas pompowania, jak mocno kiwa się i przechyla przy każdym pumpie i czy różni się to między foilami, zakrętami i prostymi. Każde takie nagranie pomaga też ulepszać rozpoznawanie pumpów dla zegarka.", "brett.erkl.daten": "Jakie dane dostajesz: kiwanie i przechył na pump, pochylenie, kadencję, zakręty kontra proste oraz ruch góra-dół (gdy rytm pompowania zostanie pewnie rozpoznany) – dla każdego przejazdu i tutaj jako przegląd wszystkich przejazdów i według foila.", "brett.erkl.mehr": "Więcej informacji", "region.earth": "Ziemia", "region.eu": "Europa", "region.af": "Afryka", "region.as": "Azja", "region.na": "Ameryka Północna", "region.sa": "Ameryka Południowa", "region.oc": "Oceania", "profile.landNone": "Nie podano", "share.errImage": "Nie udało się utworzyć obrazu", "spot.windTitle": "Okno wiatrowe", "spot.windText": "{n} sesji z wiatrem, głównie przy {a}–{b} km/h", "spot.windNote": "Skąd wiał wiatr podczas sesji wing, kite i parawing na tym spocie (wiatr z modelu).", "tab.noData": "Nie ma tu jeszcze danych.", "fontscale.label": "Wielkość czcionki", "fontscale.hint": "Powiększ wszystko dla lepszej czytelności.", "sd.avgHrTotal": "Ø tętno ogółem", "sd.whoLiked": "Kto?", "sd.likes": "Polubienia", "comments.title": "Komentarze", "comments.empty": "Jeszcze brak komentarzy. Napisz pierwszy!", "comments.placeholder": "Napisz komentarz …", "comments.offOwner": "Komentarze do twoich sesji są wyłączone.", "comments.offLink": "Włącz je w profilu", "comments.settingHint": "Inni mogą komentować twoje sesje. Możesz usuwać cudze komentarze pod swoimi sesjami. Po wyłączeniu komentarze są ukryte dla wszystkich, także te już napisane.", "comments.settingSwitch": "Zezwalaj na komentarze pod moimi sesjami", "act.title": "Nowe komentarze i polubienia", "act.comment": "skomentował(a)", "act.like": "lubi twoją sesję", "act.likeMany": "i {n} innych lubi twoją sesję", "act.session": "Sesja z {d}", "profile.land": "Narodowość", "profile.landHint": "Opcjonalnie. Jeśli ją podasz, twoja flaga pojawi się w rankingach i ich obrazach do udostępnienia.", "tab.events": "Wydarzenia", "tab.logbook": "Dziennik", "tab.rules": "Zasady", "team.einladungUngueltig": "Ten link z zaproszeniem jest już nieważny. Poproś lidera drużyny o nowy.", "team.feed30": "Sesje członków drużyny z ostatnich 30 dni.", "team.alleMeine": "Wszystkie moje drużyny", "sessions.uploadReplaceAsk": "Ta sesja już tu jest (sesja #{id}), ale plik jest inny. Usunąć starą sesję i zastąpić ją tym plikiem?\n\nSamo przycięcie nie wymaga nowego pliku: użyj „{trim}” w sesji.", "team.regeln.intro": "Jak działają drużyny na pumpfoil.org: kto co widzi, jak liczone są wyniki i co się dzieje przy usuwaniu.", "team.regeln.was.titel": "Czym jest drużyna?"]
        mpl.merge(bpl1) { a, _ in a }
        let bpl2: [String: String] = ["team.regeln.was.text": "Stała grupa z własnymi rankingami, wydarzeniami i czatem drużyny.\nKażdy może zakładać drużyny, także kilka, i należeć do kilku drużyn.\nNowa drużyna działa od razu, przez linki z zaproszeniem.", "team.regeln.rollen.titel": "Role", "team.regeln.rollen.text": "Lider może wszystko: ustawienia, rankingi, wydarzenia, wyznaczanie moderatorów, przekazanie roli lidera i usunięcie drużyny.\nModeratorzy przyjmują lub odrzucają prośby, usuwają członków i tworzą wydarzenia. Niczego więcej nie zmieniają.\nCzłonkowie widzą wszystko w drużynie i mogą ją opuścić w każdej chwili.\nLider może opuścić drużynę dopiero po przekazaniu roli lidera.", "team.regeln.beitreten.titel": "Dołączanie", "team.regeln.beitreten.text": "Jeśli drużyna przyjmuje zgłoszenia, na jej stronie jest przycisk „Dołącz”. Zależnie od ustawienia od razu jesteś członkiem albo decyduje lider lub moderator.\nSą dwa linki z zaproszeniem: jeden, z którym od razu zostajesz członkiem, i drugi, który wysyła prośbę. Oba są też dostępne jako kod QR.\nKto nie ma jeszcze konta, zakłada je i od razu jest w drużynie albo ma już wysłaną prośbę.\nNowo utworzony link zastępuje stary, który wtedy przestaje działać.\nPrzy każdym dołączeniu zgadzasz się, że rankingi drużyny mogą być publiczne, nawet jeśli teraz nie są.\nPrzy prośbie lider i moderatorzy widzą, na jakich spotach i w jakich sportach do tej pory pływałeś (tylko liczbę sesji).", "team.regeln.oeffentlich.titel": "Co jest publiczne", "team.regeln.oeffentlich.text": "Wewnątrz drużyna może wszystko. Na zewnątrz pojawia się dopiero wtedy, gdy obejrzymy i zatwierdzimy jej nazwę, adres, opis, herb i kolor.\nBaner drużyny przechodzi tę samą akceptację co herb. Którą część widać, wybiera lider bez nowej akceptacji; jeśli usunie baner, znika on od razu także ze strony publicznej.\nJeśli zatwierdzona drużyna zmieni swój wygląd, w drużynie obowiązuje to od razu, a na zewnątrz dopiero po ponownym zatwierdzeniu.\nZatwierdzone drużyny są na stronie „Wszystkie drużyny”, a ich trwające i nadchodzące wydarzenia w społeczności.\nJeśli lider ustawi rankingi jako publiczne, widzi je każdy, także bez logowania, ale tylko miejsce, nazwę wyświetlaną, inicjały i wartość. Sesje, spoty, daty i zdjęcia profilowe widzą tylko zalogowani.\nWyszukiwarki nie indeksują stron drużyn.\nLider decyduje, kto widzi listę członków: tylko członkowie czy wszyscy zalogowani.", "team.regeln.bestenlisten.titel": "Rankingi", "team.regeln.bestenlisten.text": "Każda osoba liczy się tylko raz: jej najlepsza wartość z jednej sesji, a przy sumach wszystko z wybranego okresu razem.\nLiczą się wszystkie sesje członków, także te sprzed dołączenia. Kto opuści drużynę, od razu znika z list.\nW wydarzeniach dotyczy to tylko czasu do końca, zob. „Wydarzenia”.\nObowiązują te same filtry co przy rekordach społeczności: usunięte, zgłoszone, nieprzypisane i trwające nagrania się nie liczą.\nKażdy ranking można ograniczyć do jednego sportu, jednego zakresu foili, nagrań z danymi ruchu, telefonu na desce albo spotów drużyny.\nJeśli włączone jest „Ukryj miejsce”, sesja nigdy nie liczy się dla konkretnego spotu.\nPrzy remisie wyżej jest ten, kto osiągnął wynik pierwszy.", "team.regeln.statistik.titel": "Sumy drużyny", "team.regeln.statistik.text": "Nad rankingami widać sumy wszystkich członków w wybranym okresie: pompy, dystans i czas na foilu, sesje, przejazdy oraz liczbę aktywnych członków.\nRankingu drużyna kontra drużyna celowo nie ma.", "team.regeln.logbuch.titel": "Dziennik", "team.regeln.logbuch.text": "Dziennik zapisuje, kto i kiedy pobił który rekord drużyny. Jest aktualizowany co noc.\nPierwszy wpis rankingu to stan z pierwszej nocy po jego utworzeniu.\nPrzy najlepszych wartościach liczy się każda poprawa, także własna. Przy sumach liczy się tylko objęcie prowadzenia.\nJeśli rekord spada, bo usunięto sesję albo ktoś opuścił drużynę, jest to po cichu korygowane, bez wpisu.", "team.regeln.chat.titel": "Czat drużyny", "team.regeln.chat.text": "Czat drużyny czytają i piszą w nim tylko aktywni członkowie. Kto tylko wysłał prośbę, nie widzi go.\nDla innych nie pojawia się nigdzie, także wśród aktywnych czatów.\nKto opuści drużynę albo zostanie usunięty, od razu traci dostęp i nie dostaje już powiadomień.", "team.regeln.loeschen.titel": "Usuwanie drużyny", "team.regeln.loeschen.text": "Drużynę może usunąć tylko lider i tylko po wpisaniu nazwy drużyny dla potwierdzenia.\nWtedy drużyna znika dla wszystkich: członkostwa, rankingi, dziennik, wydarzenia i czat drużyny. Na razie przechowujemy dane, aby dało się przywrócić drużynę usuniętą przez pomyłkę.\nAdres drużyny pozostaje zablokowany i nigdy nie zostanie przydzielony innej drużynie.", "team.regeln.konto.titel": "Gdy konto zostaje usunięte", "team.regeln.konto.text": "Osoba znika ze wszystkich drużyn i rankingów, a także z zamrożonych wyników wydarzeń. Osoby poniżej przesuwają się w górę.\nJeśli prowadziła drużynę, przejmuje ją najdłużej działający moderator, a jeśli go nie ma, najdłużej należący członek. Jeśli nikt nie zostanie, drużyna jest usuwana.", "team.regeln.haftung.titel": "Odpowiedzialność", "team.regeln.haftung.text": "Wydarzenia organizują same drużyny. pumpfoil.org nie ma żadnego wpływu na wydarzenia ani na składane w nich obietnice, finansowe lub inne, i nie ponosi za nie odpowiedzialności. Droga sądowa jest wykluczona. Płatności i wszelkie inne ustalenia organizatorzy i uczestnicy załatwiają między sobą, niezależnie od pumpfoil.org.\nTak samo pumpfoil.org nie ponosi odpowiedzialności za to, czy zmierzone wartości i dane są poprawne lub czy nie zostały zmanipulowane. Wyświetlane jest to, co publiczny kod źródłowy na GitHubie oblicza z przesłanych danych; innych obietnic nie ma.", "team.regeln.events.titel": "Wydarzenia", "notif.typeComment": "Komentarze do moich sesji"]
        mpl.merge(bpl2) { a, _ in a }
        r["pl"] = mpl
        var mpt: [String: String] = [:]
        let bpt0: [String: String] = ["tab.overview": "Visão geral", "tab.team": "Equipe", "tab.stats": "Estatísticas", "tab.insights": "Indicadores", "nav.settings": "Configurações", "mySpots.title": "Meus spots", "mySpots.empty": "Ainda não há sessões em nenhum spot.", "mySpots.last": "última {d}", "mySpots.since": "desde {d}", "mySpots.sports": "Esportes", "mySpots.all": "Todos ({n})", "sessions.title": "Sessões", "tab.weather": "Clima", "tab.descriptions": "Descrições", "tab.spotPage": "Página do spot", "phome.profileHint": "Sua página de perfil, como os outros podem vê-la.", "phome.asFriends": "Amigos", "phome.asAll": "Todos", "phome.previewHidden": "Sua página de perfil está oculta para os outros; só seus amigos a veem.", "ptab.privacy": "Privacidade", "ptab.watches": "Relógios", "ptab.me": "Eu", "ptab.riding": "Sessões", "ptab.display": "Aparência", "ptab.account": "Conta", "gear.title": "Equipamento", "gear.mastShim": "Mastro e shim", "gear.searchHint": "Pesquise por marca ou modelo para adicionar algo.", "gear.noHits": "Nenhum resultado.", "tab.rankings": "Recordes e classificação", "tab.media": "Mídia", "land.teamsTitle": "Equipes e eventos", "tab.map": "Mapa", "tab.list": "Lista", "tab.routes": "Rotas", "tab.watchAccounts": "Relógio e contas", "period.yesterday": "Ontem", "tab.noRecords": "Ainda não há recordes aqui.", "setup.stabSearch": "Buscar estabilizador…", "foils.hint": "Marque seus foils e escolha um como padrão (★). O padrão pode ser trocado por sessão.", "profile.avatar": "Foto de perfil", "profile.dataTitle": "Dados e conta", "profile.calculator": "Calculadora de foil", "brett.erkl.titel": "O que é a atitude da prancha?", "brett.erkl.was": "Se o seu celular estiver preso à prancha durante a sessão, o giroscópio mede como a prancha arfa e rola – direto na fonte, em vez de no pulso."]
